/**
 * MIRA_09_ProjectSelector
 *
 * Lists projects and selects validated snapshots.
 * No hardcoded snapshot IDs.
 */

const rows = $input.all().map(i => i.json);

const request =
  $('When Executed by Another Workflow').first().json || {};

const action = String(request.action || "list")
  .trim().toLowerCase();

if (!["list", "select"].includes(action)) {
  return [{
    json: {
      status: "invalid_action",
      project_count: 0,
      selected_project: null,
      projects: [],
      message: "Action must be list or select."
    }
  }];
}

const requestedName = String(request.project_name || "")
  .trim().toLowerCase();

const requestedSnapshot = String(request.snapshot_id || "")
  .trim();

// Required source documents for Mira's core capabilities.
const requiredKinds = [
  "project_description",
  "timeline",
  "risks",
  "task_board"
];

const snapshots = new Map();

function parseJSON(value) {
  if (typeof value !== "string") return value || {};
  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

for (const row of rows) {
  const id = String(row.snapshot_id || "").trim();
  if (!id) continue;

  if (!snapshots.has(id)) {
    snapshots.set(id, {
      snapshot_id: id,
      project_name: "",
      file_names: new Set(),
      document_types: new Set(),
      record_count: 0,
      latest_upload: "",
      validation_passed: false,
      validation_observed: false
    });
  }

  const s = snapshots.get(id);
  const report = parseJSON(row.validation_report);

  const name =
    String(row.project_name || report.project_name || "")
      .trim();

  if (name && !s.project_name) {
    s.project_name = name;
  }

  const file = String(row.file_name || "").trim();
  const kind = String(row.doc_kind || "").trim();

  if (file) s.file_names.add(file);
  if (kind) s.document_types.add(kind);

  s.record_count++;

  const uploaded = String(row.uploaded_at || "");

  if (uploaded > s.latest_upload) {
    s.latest_upload = uploaded;
  }

  if (typeof report.validation_passed === "boolean") {
    s.validation_observed = true;

    if (report.validation_passed === true &&
        report.ready_for_mira === true) {
      s.validation_passed = true;
    }
  }
}

const snapshotList = Array.from(snapshots.values())
  .map(s => {
    const missing = requiredKinds.filter(
      kind => !s.document_types.has(kind)
    );

    return {
      project_name: s.project_name || null,
      snapshot_id: s.snapshot_id,
      document_count: s.file_names.size,
      document_types: Array.from(s.document_types),
      missing_document_types: missing,
      record_count: s.record_count,
      latest_upload: s.latest_upload,
      validation_passed: s.validation_passed,
      validation_observed: s.validation_observed,
      complete: missing.length === 0,
      ready:
        missing.length === 0 &&
        s.validation_passed
    };
  })
  .sort((a, b) =>
    b.latest_upload.localeCompare(a.latest_upload)
  );

// Group snapshots into projects using verified names.
const groups = new Map();

for (const snapshot of snapshotList) {
  // If a name is missing, retain a separate identity.
  const key = snapshot.project_name
    ? snapshot.project_name.toLowerCase()
    : "snapshot:" + snapshot.snapshot_id;

  if (!groups.has(key)) {
    groups.set(key, {
      project_name: snapshot.project_name,
      snapshots: []
    });
  }

  groups.get(key).snapshots.push(snapshot);
}

const projects = Array.from(groups.values())
  .map(group => {
    const readySnapshots = group.snapshots
      .filter(s => s.ready);

    return {
      project_name: group.project_name,
      snapshot_count: group.snapshots.length,
      ready_snapshot_count: readySnapshots.length,
      latest_ready_snapshot_id:
        readySnapshots[0]?.snapshot_id || null,
      snapshots: group.snapshots
    };
  });

let selected = null;
let status = projects.length
  ? "available"
  : "no_projects";

if (action === "select") {
  let matches = [];

  if (requestedSnapshot) {
    matches = snapshotList.filter(
      s => s.snapshot_id === requestedSnapshot
    );
  } else if (requestedName) {
    matches = snapshotList.filter(
      s => s.project_name &&
      s.project_name.toLowerCase() === requestedName
    );
  }

  const readyMatches = matches.filter(s => s.ready);

  if (readyMatches.length) {
    selected = readyMatches[0];
    status = "selected";
  } else {
    status = matches.length
      ? "not_ready"
      : "selection_required";
  }
}

return [{
  json: {
    status,
    project_count: projects.length,
    snapshot_count: snapshotList.length,
    selected_project: selected,
    projects
  }
}];
